package com.pocketmusic.android;

import android.app.*;
import android.content.res.ColorStateList;
import android.graphics.Bitmap;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import static com.pocketmusic.android.DesignTokens.*;

/** Focused native saved-audio screen; no hidden or duplicate YouTube player. */
final class NowPlayingSheet extends Dialog {
 interface Actions {void toggle();void step(int direction);void seek(double seconds);void volume(int percent);void shuffle();void repeat();void queue();void sleep();void like();boolean liked();}
 private final Activity owner;private final Actions actions;
 private ImageButton favorite,shuffle;private TextView title,artist,source,playbackState,elapsed,total,queuePosition;private ImageView cover;private PlayerButton play;private Button repeat,timer;private SeekBar seek,volume;
 private boolean tracking,volumeTracking;private double duration;private Bitmap lastCover;private String lastTitle="",metadataPath="";
 NowPlayingSheet(Activity owner,Actions actions){super(owner,R.style.AppTheme);this.owner=owner;this.actions=actions;}
 @Override protected void onCreate(Bundle saved){
  super.onCreate(saved);Window w=getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setStatusBarColor(COLOR_BG);w.setNavigationBarColor(COLOR_BG);}
  LinearLayout root=column();root.setPadding(dp(24),dp(12),dp(24),dp(24));root.setBackgroundColor(COLOR_BG);
  LinearLayout heading=row();ImageButton close=UiComponents.icon(owner,R.drawable.ic_lucide_chevron_down,"Close now playing",this::dismiss);heading.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));TextView label=text("NOW PLAYING",TYPE_CAPTION);label.setLetterSpacing(.14f);label.setGravity(Gravity.CENTER);label.setTextColor(COLOR_TEXT_MUTED);heading.addView(label,new LinearLayout.LayoutParams(0,dp(48),1));ImageButton menu=UiComponents.icon(owner,R.drawable.ic_lucide_ellipsis,"Player options",()->{PopupMenu p=new PopupMenu(owner,heading);p.getMenu().add("Sleep timer").setOnMenuItemClickListener(i->{actions.sleep();return true;});p.getMenu().add("Queue").setOnMenuItemClickListener(i->{actions.queue();return true;});p.show();});heading.addView(menu,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(heading);
  View topSpace=new View(owner);root.addView(topSpace,new LinearLayout.LayoutParams(1,dp(20),1));
  cover=new ImageView(owner);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setContentDescription("Current track artwork");GradientDrawable frame=new GradientDrawable();frame.setColor(COLOR_SURFACE);frame.setCornerRadius(dp(12));cover.setBackground(frame);cover.setClipToOutline(true);
  int edge=Math.min(dp(320),Math.min(owner.getResources().getDisplayMetrics().widthPixels-dp(80),(int)(owner.getResources().getDisplayMetrics().heightPixels*.33f)));LinearLayout.LayoutParams picture=new LinearLayout.LayoutParams(edge,edge);picture.gravity=Gravity.CENTER_HORIZONTAL;picture.bottomMargin=dp(28);root.addView(cover,picture);
  source=text("SAVED AUDIO",TYPE_CAPTION);source.setTextColor(COLOR_TEXT_MUTED);source.setGravity(Gravity.CENTER);source.setLetterSpacing(.08f);root.addView(source);playbackState=text("",TYPE_CAPTION);playbackState.setTextColor(COLOR_ACCENT);playbackState.setGravity(Gravity.CENTER);playbackState.setPadding(0,dp(8),0,0);root.addView(playbackState);
  LinearLayout info=row();info.setPadding(dp(4),dp(12),0,dp(8));LinearLayout words=column();title=text("",24);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(title);artist=text("Pocket Music",TYPE_BODY);artist.setMaxLines(1);artist.setEllipsize(android.text.TextUtils.TruncateAt.END);artist.setTextColor(COLOR_TEXT_MUTED);artist.setPadding(0,dp(8),0,0);words.addView(artist);info.addView(words,new LinearLayout.LayoutParams(0,-2,1));favorite=UiComponents.icon(owner,R.drawable.ic_lucide_heart,"Like current song",actions::like);info.addView(favorite,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(info);
  seek=new SeekBar(owner);seek.setMax(1000);seek.setMinimumHeight(dp(48));seek.setContentDescription("Expanded playback position");tint(seek);root.addView(seek);
  LinearLayout times=row();elapsed=text("0:00",TYPE_CAPTION);total=text("0:00",TYPE_CAPTION);queuePosition=text("",TYPE_CAPTION);for(TextView t:new TextView[]{elapsed,total,queuePosition})t.setTextColor(COLOR_TEXT_MUTED);times.addView(elapsed);queuePosition.setGravity(Gravity.CENTER);times.addView(queuePosition,new LinearLayout.LayoutParams(0,-2,1));times.addView(total);root.addView(times);
  seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){tracking=true;}public void onStopTrackingTouch(SeekBar s){actions.seek(duration*s.getProgress()/1000);tracking=false;}public void onProgressChanged(SeekBar s,int p,boolean user){if(user)elapsed.setText(clock(duration*p/1000));}});
  LinearLayout transport=row();transport.setGravity(Gravity.CENTER);transport.setPadding(0,dp(20),0,dp(16));shuffle=UiComponents.icon(owner,R.drawable.ic_lucide_shuffle,"Shuffle",actions::shuffle);transport.addView(shuffle,new LinearLayout.LayoutParams(0,dp(48),1));transport.addView(UiComponents.icon(owner,R.drawable.ic_lucide_skip_back,"Previous track",()->actions.step(-1)),new LinearLayout.LayoutParams(dp(56),dp(56)));
  play=new PlayerButton(owner,"play");play.setOnClickListener(v->actions.toggle());GradientDrawable circle=new GradientDrawable();circle.setColor(COLOR_ACCENT);circle.setShape(GradientDrawable.OVAL);play.setBackground(circle);LinearLayout.LayoutParams primary=new LinearLayout.LayoutParams(dp(76),dp(76));primary.leftMargin=primary.rightMargin=dp(12);transport.addView(play,primary);transport.addView(UiComponents.icon(owner,R.drawable.ic_lucide_skip_forward,"Next track",()->actions.step(1)),new LinearLayout.LayoutParams(dp(56),dp(56)));repeat=button("↻",actions::repeat);repeat.setTextSize(24);transport.addView(repeat,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(transport);
  LinearLayout options=row();timer=button("Timer",actions::sleep);Button queue=button("Queue",actions::queue),sound=button("Sound",()->{volume.setVisibility(volume.getVisibility()==View.GONE?View.VISIBLE:View.GONE);});for(Button b:new Button[]{timer,queue,sound})options.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));root.addView(options);
  volume=new SeekBar(owner);volume.setMax(100);volume.setMinimumHeight(dp(48));volume.setContentDescription("Expanded playback volume");tint(volume);volume.setVisibility(View.GONE);root.addView(volume);volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){volumeTracking=true;}public void onStopTrackingTouch(SeekBar s){volumeTracking=false;}public void onProgressChanged(SeekBar s,int p,boolean user){if(user)actions.volume(p);}});
  root.addView(new View(owner),new LinearLayout.LayoutParams(1,dp(16),1));ScrollView scroll=new ScrollView(owner);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);scroll.addView(root);scroll.setBackgroundColor(COLOR_BG);scroll.setOnApplyWindowInsetsListener((v,insets)->{int top,bottom;if(android.os.Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars());top=bars.top;bottom=bars.bottom;}else{top=insets.getSystemWindowInsetTop();bottom=insets.getSystemWindowInsetBottom();}v.setPadding(0,top,0,bottom);return insets;});setContentView(scroll);
 }
 @Override public void show(){super.show();Window w=getWindow();if(w!=null){w.setLayout(-1,-1);w.setGravity(Gravity.CENTER);}}
 void update(String name,String hint,Bitmap image,boolean playing,double position,double length,int percent,boolean shuffled,int repeatMode){
  if(title==null)return;title.setText(name);duration=length;play.setPlaying(playing);play.setContentDescription(playing?"Pause":"Play");LocalPlayerService player=LocalPlayerService.active;String path=player==null?"":player.online&&player.song!=null?"online:"+player.song.id+":"+player.networkPlayback:player.path;if(!path.equals(metadataPath)){metadataPath=path;Track song=player!=null&&player.online?player.song:MusicTaste.track(owner,TrackFiles.videoId(new java.io.File(path)));artist.setText(song!=null&&!song.artist.isEmpty()?song.artist:player!=null&&player.networkPlayback?"Pocket Music · Online audio":"Pocket Music · Local audio");String format=player!=null&&player.networkPlayback?"STREAM":player==null||player.path.isEmpty()?"AUDIO":player.path.substring(player.path.lastIndexOf('.')+1).toUpperCase(java.util.Locale.ROOT);source.setText(format+(player!=null&&player.networkPlayback?"  ·  ONLINE":"  ·  OFFLINE"));}String state=player==null?hint:player.state;String stateLabel="preparing".equals(state)?"Preparing audio…":"buffering".equals(state)?"Buffering…":player!=null&&!player.error.isEmpty()?"Playback needs attention":playing?"": "Paused";playbackState.setText(stateLabel);playbackState.setVisibility(stateLabel.isEmpty()?View.GONE:View.VISIBLE);long left=SleepTimer.remaining(owner);timer.setText(left>0?"Timer · "+((left+59999)/60000)+"m":"Timer");timer.setContentDescription(left>0?"Sleep timer: "+((left+59999)/60000)+(((left+59999)/60000)==1?" minute remaining":" minutes remaining"):"Sleep timer off");queuePosition.setText(player==null?"":(player.queueOrder().indexOf(player.queueIndex())+1)+" / "+player.queueOrder().size());
  favorite.setEnabled(player==null||!player.online||player.song!=null&&player.song.music);boolean liked=actions.liked();favorite.setImageTintList(ColorStateList.valueOf(liked?COLOR_DANGER:COLOR_TEXT_MUTED));favorite.setContentDescription(liked?"Unlike current song":"Like current song");if(!tracking){seek.setProgress(length>0?(int)(position*1000/length):0);elapsed.setText(clock(position));}seek.setEnabled(length>0);total.setText(clock(length));if(!volumeTracking)volume.setProgress(percent);
  if(image!=lastCover||(image==null&&!name.equals(lastTitle))){lastCover=image;lastTitle=name;if(image==null)cover.setImageDrawable(new TrackCoverDrawable(name));else cover.setImageBitmap(image);}
  shuffle.setImageTintList(ColorStateList.valueOf(shuffled?COLOR_ACCENT:COLOR_TEXT_MUTED));shuffle.setContentDescription(shuffled?"Shuffle on":"Shuffle");shuffle.setSelected(shuffled);repeat.setText(repeatMode==2?"↻¹":"↻");repeat.setTextColor(repeatMode==0?COLOR_TEXT_MUTED:COLOR_ACCENT);repeat.setContentDescription(repeatMode==1?"Repeat all":repeatMode==2?"Repeat one":"Repeat");repeat.setSelected(repeatMode!=0);
 }
 private Button button(String name,Runnable run){Button b=new androidx.appcompat.widget.AppCompatButton(owner);b.setAllCaps(false);b.setText(name);b.setTextSize(TYPE_CAPTION);b.setTextColor(COLOR_TEXT_MUTED);b.setMinHeight(dp(48));b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(0,0,0,0);b.setBackground(GlassTheme.ghost(owner));b.setStateListAnimator(null);b.setOnClickListener(v->run.run());return b;}
 private TextView text(String value,int size){TextView t=new TextView(owner);t.setText(value);t.setTextSize(size);t.setTextColor(COLOR_TEXT);t.setIncludeFontPadding(false);return t;}
 private LinearLayout row(){LinearLayout l=column();l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private LinearLayout column(){LinearLayout l=new LinearLayout(owner);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private void tint(SeekBar s){s.setProgressTintList(ColorStateList.valueOf(COLOR_ACCENT));s.setThumbTintList(ColorStateList.valueOf(COLOR_ACCENT));}
 private int dp(int value){return GlassTheme.dp(owner,value);}
 private static String clock(double seconds){int s=(int)Math.max(0,seconds);return String.format(java.util.Locale.ROOT,"%d:%02d",s/60,s%60);}
}
